const token=localStorage.getItem('owar-admin-token')||prompt('Enter the admin token');if(token)localStorage.setItem('owar-admin-token',token);
const auth={Authorization:`Bearer ${token}`}, $=s=>document.querySelector(s);
async function request(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:{...auth,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error('Authentication failed');return r.json()}
async function render(){try{const d=await request('/api/admin/status'),paused=d.meta.feed_paused==='true';$('#event-status').value=d.meta.status||'Live';$('#event-list').innerHTML=d.events.map(e=>`<div class="event-row"><div><h3>${e.name}</h3><p>${e.count} imported results · ${e.visible?'Visible publicly':'Hidden'}</p></div><label class="switch"><input type="checkbox" data-id="${e.id}" ${e.visible?'checked':''}><span class="slider"></span></label></div>`).join('');$('#event-list').querySelectorAll('input').forEach(x=>x.onchange=async()=>{await request(`/api/admin/events/${x.dataset.id}`,{visible:x.checked});render()});$('#source-list').innerHTML=d.sources.map(s=>`<label class="switch"><span>${s.url}</span><input type="checkbox" data-source="${s.rowid}" ${s.active?'checked':''}><span class="slider"></span></label>`).join('');$('#source-list').querySelectorAll('input').forEach(x=>x.onchange=async()=>{await request(`/api/admin/sources/${x.dataset.source}`,{active:x.checked});render()});$('#simulate').textContent=paused?'Start live updates':`Stop live updates (${d.pollSeconds}s)`;$('#simulate').disabled=false;$('#simulate').onclick=async()=>{await request('/api/admin/feed',{running:paused});render()};$('#reset').textContent=`Last import: ${d.meta.last_import||'waiting'}`;$('#reset').disabled=true}catch(e){$('#event-list').innerHTML='<p>Could not connect. Check the admin token and service configuration.</p>'}}
$('#add-source').onclick=async()=>{const input=$('#source-url');if(!input.value.trim())return;await request('/api/admin/sources',{url:input.value.trim()});input.value='';render()};
$('#event-status').onchange=()=>request('/api/admin/status',{status:$('#event-status').value});render();
